# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAÛN SURESİ (107. SURE) — GENEL ÖZELLİKLER VE KONUSU</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Surenin Kimliği ve Temel Kavramları</text>\n  <text x="180" y="95" text-anchor="middle" font-size="12" fill="#1e3a8a">• Mekke Dönemi\'nde inmiştir, 7 ayettir.</text>\n  <text x="180" y="118" text-anchor="middle" font-size="12" fill="#1e3a8a">• Kur\'an-ı Kerim\'in 107. suresidir (30. cüz).</text>\n  <text x="180" y="141" text-anchor="middle" font-size="12" fill="#1e3a8a">• Adını son ayetteki "el-Mâûn" kelimesinden alır.</text>\n  <text x="180" y="167" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Maûn: Yardım, Zekât ve Komşuluk Eşyası</text>\n  <text x="180" y="192" text-anchor="middle" font-size="12" fill="#1e3a8a">• Din (ed-Dîn): Ahiret günü / Hesap ve ceza günü</text>\n  <text x="180" y="217" text-anchor="middle" font-size="12" fill="#1e3a8a">• Riya (المراءاة): İbadeti gösteriş için yapma</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Surede Eleştirilen İki İnsan Tipi</text>\n  <text x="520" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. Hesap Gününü (Dini) Yalanlayanlar (Ayet 1-3)</text>\n  <text x="520" y="117" text-anchor="middle" font-size="11" fill="#7f1d1d">• Yetimi (babası ölmüş çocuğu) itip kakarlar.</text>\n  <text x="520" y="137" text-anchor="middle" font-size="11" fill="#7f1d1d">• Yoksulu doyurmaya teşvik etmez, önayak olmazlar.</text>\n  <text x="520" y="165" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">2. Namazından Gafil ve Riyakâr Olanlar (Ayet 4-7)</text>\n  <text x="520" y="187" text-anchor="middle" font-size="11" fill="#7f1d1d">• Namazlarını ciddiye almaz, bilincinden uzaktırlar.</text>\n  <text x="520" y="207" text-anchor="middle" font-size="11" fill="#7f1d1d">• İbadetlerini insanlara gösteriş (riya) için yaparlar.</text>\n  <text x="520" y="227" text-anchor="middle" font-size="11" fill="#7f1d1d">• En küçük yardımı (maûn / zekât) bile esirgerler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAÛN SURESİNDEN ÇIKARILACAK AHLAKİ İLKELER (İHLAS VE İNFAK)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. Yetim ve Yoksul Hakkı</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#14532d">• Yetimlere şefkat ve</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#14532d">merhametle yaklaşmak</text>\n  <text x="125" y="140" text-anchor="middle" font-size="11" fill="#14532d">• Yoksulları gözetmek ve</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#14532d">hayır işlerine öncülük etmek</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Ahiret İnancı → Merhamet</text>\n  <text x="125" y="210" text-anchor="middle" font-size="10" fill="#14532d">Hesap gününe inanan kimse</text>\n  <text x="125" y="225" text-anchor="middle" font-size="10" fill="#14532d">muhtaçların hakkını korur.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">2. İbadette Samimiyet (İhlas)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#713f12">• Namazı huşu ve bilinç</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#713f12">içinde vaktinde kılmak</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11" fill="#713f12">• Gösterişten (riya) uzak</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" fill="#713f12">durup Allah rızasını aramak</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">İhlas x Riya (Gösteriş)</text>\n  <text x="350" y="210" text-anchor="middle" font-size="10" fill="#713f12">Sağ elin verdiğini sol el</text>\n  <text x="350" y="225" text-anchor="middle" font-size="10" fill="#713f12">görmeyecek şekilde gizli vermek.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. Yardımlaşma (Maûn)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#581c87">• Zekât ve sadaka ibadetini</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#581c87">gönülden yerine getirmek</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#581c87">• Komşulukta en küçük</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#581c87">ev eşyasını esirgememek</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">İbadet — Ahlak Bütünlüğü</text>\n  <text x="575" y="210" text-anchor="middle" font-size="10" fill="#581c87">Gerçek dindarlık ibadeti</text>\n  <text x="575" y="225" text-anchor="middle" font-size="10" fill="#581c87">paylaşma ahlakıyla birleştirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE: ZEKÂT VE SADAKA — BÜTÜNCÜL DEĞERLENDİRME ŞEMASI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">İnfak, Zekât ve Sadaka Özeti</text>\n  <text x="180" y="95" text-anchor="middle" font-size="11" fill="#164e63">• İnfak: Allah rızası için maldan harcama yapma</text>\n  <text x="180" y="117" text-anchor="middle" font-size="11" fill="#164e63">• Zekât: Nisap miktarı mala sahip olanlara farz (yılda 1)</text>\n  <text x="180" y="139" text-anchor="middle" font-size="11" fill="#164e63">• Oranlar: Altın/para %2,5, Koyun 40\'ta 1, Sığır 30\'da 1</text>\n  <text x="180" y="161" text-anchor="middle" font-size="11" fill="#164e63">• Verilecekler: Tevbe 60 (8 sınıf; anne-baba-eş-çocuğa verilmez)</text>\n  <text x="180" y="183" text-anchor="middle" font-size="11" fill="#164e63">• Sadaka-i Fıtır (Fitre): Ramazan\'da vacip (varlık şükrü)</text>\n  <text x="180" y="205" text-anchor="middle" font-size="11" fill="#164e63">• Sadaka-i Cariye: Kesintisiz sevap (okul, çeşme, ilim, evlat)</text>\n  <text x="180" y="225" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Bireysel Fayda: Cimriliği yener · Toplumsal: Sosyal adalet</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Hz. Şuayb (as) ve Maûn Suresi Mesajı</text>\n  <text x="520" y="95" text-anchor="middle" font-size="11" fill="#881337">• Hz. Şuayb (as): Medyen ve Eyke halkına gönderildi.</text>\n  <text x="520" y="117" text-anchor="middle" font-size="11" fill="#881337">• Çağrısı: Tevhid + Ölçü ve tartıda hile yapmama.</text>\n  <text x="520" y="139" text-anchor="middle" font-size="11" fill="#881337">• "Hatîbü\'l-Enbiyâ" (Peygamberlerin Hatibi) unvanı.</text>\n  <text x="520" y="165" text-anchor="middle" font-size="11" fill="#881337">• Maûn Suresi: Yetimi koruma, yoksulu doyurma,</text>\n  <text x="520" y="185" text-anchor="middle" font-size="11" fill="#881337">namazda ihlas (riyadan kaçınma) ve yardımı esirgememe.</text>\n  <text x="520" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Ortak İlke: Kul Hakkı, Adalet ve Samimi Paylaşım</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
